insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,clinical_judgment_step,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale) values
('86000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000001',1,'The RN is assessing a client with COPD. Which new finding requires the highest priority assessment?','single_best_answer',array['rn'],'Adult Health: Respiratory','COPD','Physiological Integrity','Prioritize Hypotheses','medium','New increasing somnolence with worsening work of breathing is a significant change that may indicate deteriorating ventilation. The RN should rapidly reassess respiratory status and coordinate the appropriate response.','Chronic cough, established activity intolerance, and routine teaching needs are important but do not outweigh an acute change in ventilation or mental status.','RN respiratory priority: new mental-status change plus worsening breathing signals deterioration.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','RN comprehensive respiratory assessment, synthesis of acute changes, and prioritization of deterioration.','RN-specific because the learner must integrate respiratory and neurologic cues and reprioritize the overall nursing response.'),
('86000000-0000-4000-8000-000000000002','85000000-0000-4000-8000-000000000002',1,'The LPN/VN is caring for a client with COPD whose chronic cough is unchanged. Which new finding should be reported promptly?','single_best_answer',array['pn'],'Adult Health: Respiratory','COPD','Physiological Integrity','Recognize Cues','medium','New increasing drowsiness with greater work of breathing represents a meaningful change from baseline. The LPN/VN should collect focused respiratory data, maintain safety, and promptly communicate/escalate the change according to the setting.','An unchanged chronic cough or routine care need does not carry the same urgency as new respiratory and mental-status deterioration.','PN respiratory priority: compare with baseline; new breathing plus mentation change needs prompt escalation.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','PN recognition of respiratory change, focused data collection, safety, and prompt communication.','PN-specific because the learner identifies deterioration from baseline and communicates it within the established care structure.'),
('86000000-0000-4000-8000-000000000003','85000000-0000-4000-8000-000000000003',1,'The RN is reassessing a client with pneumonia. Which finding most strongly suggests worsening oxygenation and perfusion?','single_best_answer',array['rn'],'Adult Health: Respiratory','Pneumonia','Physiological Integrity','Analyze Cues','medium','New confusion, increasing respiratory effort, and cool skin form a concerning cluster suggesting impaired oxygenation and systemic perfusion. The RN should treat the change as urgent and reassess comprehensively.','An unchanged productive cough, fatigue, or appetite change may accompany pneumonia but does not indicate the same degree of acute deterioration.','RN: respiratory deterioration is a pattern — breathing, mentation, and perfusion cues matter together.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','RN synthesis of respiratory, neurologic, and perfusion cues to identify worsening illness.','RN-specific because the learner integrates multiple systems rather than responding to one isolated finding.'),
('86000000-0000-4000-8000-000000000004','85000000-0000-4000-8000-000000000004',1,'The LPN/VN is monitoring a client with pneumonia. Which change should be communicated most promptly?','single_best_answer',array['pn'],'Adult Health: Respiratory','Pneumonia','Physiological Integrity','Recognize Cues','medium','New confusion with increased work of breathing is a significant departure from baseline and may indicate worsening oxygenation. Focused assessment, safety, and prompt communication are appropriate.','Stable fatigue, an unchanged cough, or routine requests do not indicate the same acute change.','PN pneumonia monitoring: new confusion plus harder breathing is not routine — reassess and report.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','PN focused monitoring for worsening oxygenation and communication of significant change.','PN-specific because the learner detects and reports a new clinical change while continuing care under the established plan.'),
('86000000-0000-4000-8000-000000000005','85000000-0000-4000-8000-000000000005',1,'The RN is assessing a client during an acute asthma exacerbation. Which change is most concerning?','single_best_answer',array['rn'],'Adult Health: Respiratory','Asthma','Physiological Integrity','Analyze Cues','medium','A client who becomes exhausted with markedly diminished air movement despite ongoing distress may be deteriorating. Less audible wheezing is not necessarily improvement when airflow is severely reduced.','Persistent wheezing with adequate air movement or anxiety may require treatment, but sudden fatigue and diminished airflow are more concerning for impending respiratory failure.','Asthma trap: a quieter chest can mean less airflow, not improvement.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','RN interpretation of changing respiratory assessment findings and recognition of impending failure.','RN-specific because the learner must interpret the meaning of changing breath sounds in the context of the whole respiratory assessment.'),
('86000000-0000-4000-8000-000000000006','85000000-0000-4000-8000-000000000006',1,'The LPN/VN is monitoring a client with an asthma exacerbation. Which new finding requires immediate communication?','single_best_answer',array['pn'],'Adult Health: Respiratory','Asthma','Physiological Integrity','Recognize Cues','medium','New exhaustion with markedly decreased air movement is a significant deterioration and requires immediate focused assessment, safety measures, and escalation.','A client who still has wheezing but is alert and moving air does not show the same degree of deterioration as one becoming exhausted with very poor airflow.','PN asthma cue: worsening fatigue plus less air movement is an emergency change to report.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','PN recognition of respiratory deterioration and immediate communication/escalation.','PN-specific because the learner monitors the established condition, recognizes a dangerous change, and escalates promptly.'),
('86000000-0000-4000-8000-000000000007','85000000-0000-4000-8000-000000000007',1,'The RN receives report on four clients. Which client should the RN assess first?','single_best_answer',array['rn'],'Adult Health: Respiratory','Pulmonary Embolism','Physiological Integrity','Prioritize Hypotheses','medium','Sudden unexplained dyspnea with pleuritic chest discomfort and tachycardia after a period of immobility is concerning for pulmonary embolism and requires immediate assessment.','Stable chronic respiratory findings and routine teaching needs are lower priority than a sudden potentially life-threatening change.','RN priority: sudden dyspnea plus PE risk factors outranks stable chronic findings.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','RN prioritization across clients using acute respiratory cues and thromboembolic risk.','RN-specific because the learner synthesizes handoff information across multiple clients and selects the highest physiologic threat.'),
('86000000-0000-4000-8000-000000000008','85000000-0000-4000-8000-000000000008',1,'The LPN/VN is caring for a client who has been relatively immobile. Which new finding should be reported immediately?','single_best_answer',array['pn'],'Adult Health: Respiratory','Pulmonary Embolism','Physiological Integrity','Recognize Cues','medium','Sudden unexplained shortness of breath with pleuritic chest discomfort and a rapid pulse is a significant acute change that may indicate pulmonary embolism. The LPN/VN should maintain safety, collect focused data as appropriate, and immediately escalate according to the setting.','Routine discomfort, stable chronic symptoms, or nonurgent teaching needs do not have the same implication for sudden cardiopulmonary deterioration.','PN PE cue: sudden dyspnea after immobility is a change to recognize and escalate immediately.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','PN recognition of sudden cardiopulmonary change and immediate communication/escalation.','PN-specific because the learner recognizes a potentially life-threatening change and acts within the established response structure.')
insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values
