('86000000-0000-4000-8000-000000000005','a','The client has audible wheezing but remains alert and moves air bilaterally.',false,'This requires treatment but is less concerning than exhaustion with severely reduced airflow.',1),('86000000-0000-4000-8000-000000000005','b','The client becomes exhausted and breath sounds are markedly diminished despite ongoing distress.',true,'This may signal critically reduced airflow and impending respiratory failure.',2),('86000000-0000-4000-8000-000000000005','c','The client says the episode is frightening.',false,'Anxiety is expected and does not outweigh signs of respiratory failure.',3),('86000000-0000-4000-8000-000000000005','d','The client asks how to avoid future triggers.',false,'Teaching is not the immediate priority.',4),
('86000000-0000-4000-8000-000000000006','a','The client remains alert with wheezing and is able to speak.',false,'This is less concerning than exhaustion with poor airflow.',1),('86000000-0000-4000-8000-000000000006','b','The client becomes exhausted and air movement is markedly decreased.',true,'This is a dangerous change requiring immediate escalation.',2),('86000000-0000-4000-8000-000000000006','c','The client asks about avoiding triggers.',false,'Teaching is nonurgent during deterioration.',3),('86000000-0000-4000-8000-000000000006','d','The client requests a family member.',false,'This does not indicate respiratory status.',4),
